import {createRecordsStore,RECORDS_KEY} from './case-records.js';
import {createSpecialSupport} from './support-view.js';
import {installDatePickers} from './date-picker.js';
import {createRecordsView} from './records-view.js';
import {rightsGuideHtml} from './rights-guide.js';
import {enhanceTerms} from './terms.js';
import {STORAGE_KEY} from './age.js';
import {createPageStorage,clearLegacyPersonalData} from './session-state.js';
import {normalizeCaseProfile,normalizeFamilySituation,selectFamilySituation,newSituationId,CASE_STAGES,CASE_ROLES} from './case-profile.js';
import {caseOnboardingHtml,bindCaseProfileForm} from './case-onboarding.js';
import {createPlanner,refreshIcon} from './planner.js';
import {createNotesStore,NOTES_KEY} from './notes.js';
import {createCalculatorStore,CALCULATOR_STORAGE_KEY} from './calculator-storage.js';
import {createIntegratedCalculator,calcIcon} from './calculator.js';
import {calcEscape as esc} from './calculator-view.js';
import {calendarDate} from './polish.js';
import {createDataWorkspace} from './data-workspace.js';
const app=document.querySelector('#app'),sheet=document.querySelector('#sheet');
installDatePickers();
const brand=()=>'<div class="brand"><img src="assets/logo.svg" alt="Logo aplikacji"><div class="brand-copy"><b><span>Przewodnik</span><span>Przyszłego Rodzica</span></b><small>Świadczenia. Urlopy. Wasz plan.</small></div></div>';
const svg=path=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
const icons={calendar:svg('<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18"/>'),documents:svg('<path d="M6 2h8l4 4v16H6zM14 2v5h4M9 12h6m-6 4h6"/>'),profile:svg('<circle cx="12" cy="8" r="4"/><path d="M5 22v-3a7 7 0 0 1 14 0v3"/>')};
let profile=null,active='guide',observer,toastTimer,storageAvailable=true;
const pageStorage=createPageStorage();
for(const kind of ['localStorage','sessionStorage'])try{clearLegacyPersonalData(globalThis[kind]);globalThis[kind]?.removeItem(STORAGE_KEY);}catch{/* Restricted storage does not affect this page's in-memory data. */}
window.addEventListener('pagehide',()=>pageStorage.clear());
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();});
const getStorage=()=>pageStorage;
const notesStore=createNotesStore({getStorage}),calculatorStore=createCalculatorStore({getStorage}),recordsStore=createRecordsStore({getStorage});
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function persist(patch){const next=normalizeCaseProfile({...profile,...patch},{isNew:!profile});try{pageStorage.setItem(STORAGE_KEY,JSON.stringify(next));storageAvailable=true;}catch{storageAvailable=false;notify('Nie udało się zapisać zmian. Pozostają dostępne do zamknięcia tej karty.');}profile=next;return next;}
function sheetContent(title,body){if(sheet.open)sheet.close();sheet.innerHTML=`<div class="sheet-body"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-heading"><h2 id="sheet-title">${esc(title)}</h2><button id="close-sheet" class="icon-button" aria-label="Zamknij">×</button></div>${body}</div>`;enhanceTerms(sheet.querySelector('.sheet-body'));sheet.querySelector('#close-sheet').onclick=()=>sheet.close();sheet.showModal();}
const planner=createPlanner({getProfile:()=>profile,persist,sheetContent,notify,notesStore,calculatorStore,recordsStore,openRecords:kind=>recordsView.open(kind),openCalculator:id=>show('calculator',id)});
const calculator=createIntegratedCalculator({recordsStore,openRecords:()=>recordsView.open(),getProfile:()=>profile,store:calculatorStore,sheetContent,notify,onChange:()=>{if(active==='calendar')show('calendar');},openCalendar:()=>show('calendar'),onDocumentsApplied:()=>show('calculator')});
const recordsView=createRecordsView({store:recordsStore,calculatorStore,sheetContent,notify,onChange:()=>{calculator.invalidateRules();if(active==='calendar')show('calendar');},onUseRecord:patch=>{calculator.importData(patch);sheet.close();show('calculator');}});
const specialSupport=createSpecialSupport({sheet,sheetContent,getProfile:()=>profile,store:calculatorStore,recordsStore,notify,openRecords:()=>recordsView.open()});
const dataWorkspace=createDataWorkspace({getProfile:()=>profile,persist,sheetContent,notify,openCalculator:()=>{calculator.useProfile();show('calculator');},openForms:()=>{show('calculator');calculator.openTools();},onRefreshSources:planner.refresh,onSourceStatus:planner.openStatus,openSupport:showSpecialSupport,openDocuments:()=>calculator.openDocuments(),onImport:patch=>{calculator.importData(patch);show('calculator');}});
function layout(){const main=app.querySelector('.workspace-main');if(main){const nav=app.querySelector('.bottom-nav'),desktop=matchMedia('(min-width:900px)').matches;main.style.top=app.querySelector('.app-header').offsetHeight+'px';main.style.bottom=desktop?'0px':nav.offsetHeight+'px';main.style.left=desktop?nav.offsetWidth+'px':'0px';}}
function shell(){observer?.disconnect();app.innerHTML=`<header class="app-header case-header"><div class="top-row">${brand()}<div class="top-actions"><button id="edit-top" class="icon-button" aria-label="Mój profil">${icons.profile}</button></div></div></header><nav class="bottom-nav" aria-label="Nawigacja główna">${[['guide','Przewodnik',icons.documents],['calculator','Zintegrowany Kalkulator',calcIcon()],['calendar','Kalendarz',icons.calendar],['documents','Dane i dokumenty',icons.documents],['profile','Mój profil',icons.profile]].map(([key,label,icon])=>`<button id="nav-${key}" class="nav-item" data-nav="${key}" aria-label="${label}"><span class="nav-icon">${icon}</span><span><span class="nav-full-label">${label}</span><span class="nav-short-label">${({guide:'Start',calculator:'Kalkulator',calendar:'Kalendarz',documents:'Dokumenty',profile:'Profil'})[key]||label}</span></span></button>`).join('')}</nav>`;app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>show(b.dataset.nav));app.querySelector('#edit-top').onclick=()=>show('profile');observer=new ResizeObserver(layout);for(const el of [app,app.querySelector('.app-header'),app.querySelector('.bottom-nav')])observer.observe(el);}
function show(tab='guide',id){if(!profile&&!['calculator'].includes(tab))return onboarding();active=tab;if(!app.querySelector('.bottom-nav'))shell();app.querySelector('.workspace-main')?.remove();const main=document.createElement('main');main.id=tab==='calculator'?'calculator-view':tab==='calendar'?'calendar-view':tab+'-view';main.className='workspace-main';app.querySelector('.bottom-nav').before(main);app.querySelectorAll('[data-nav]').forEach(b=>{const selected=b.dataset.nav===tab;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(tab==='guide'){main.classList.add('case-content');renderGuide(main);}else if(tab==='calculator'){calculator.mount(main,id);main.classList.add('workspace-main');}else if(tab==='calendar'){main.classList.add('calendar-view');main.innerHTML=planner.calendarHtml();planner.bindCalendar(main);}else if(tab==='documents'){main.classList.add('case-content');dataWorkspace.mount(main);const journal=document.createElement('button');journal.className='secondary';journal.id='open-case-records';journal.textContent='Moje dokumenty, decyzje i wypłaty';journal.onclick=()=>recordsView.open();main.prepend(journal);}else{main.classList.add('case-content');renderProfile(main);}enhanceTerms(main);layout();}
function onboarding(edit=false){observer?.disconnect();app.innerHTML=caseOnboardingHtml(brand(),edit?profile:{},edit);bindCaseProfileForm(app,data=>{persist({...data,formal:true,onboardingComplete:true});if(!storageAvailable)notify('Profil działa w tej karcie; zapis jest niedostępny.');calculator.useProfile();shell();show('guide');},{profile:edit?profile:{},edit,onSpecial:showSpecialSupport});const docs=document.createElement('button');docs.className='secondary';docs.id='onboarding-documents';docs.textContent='Sprawdź sprawę na podstawie dokumentów — bez logowania';docs.onclick=()=>calculator.openDocuments();app.querySelector('.case-start-intro img').before(docs);}
function showSpecialSupport(){specialSupport.open();}
function renderGuide(main){main.innerHTML=`<div class="case-page-heading"><span class="eyebrow">Przewodnik Przyszłego Rodzica</span><h1>Świadczenia, urlopy i formalności — po kolei</h1><p>Możesz zacząć od ogólnych informacji. Kalkulator poprosi o dane dopiero wtedy, gdy zechcesz sprawdzić własną sytuację.</p></div><div class="case-guide-summary"><span>${esc(CASE_STAGES[profile.caseStage])}</span><strong>${esc(profile.name||'Wybrana sytuacja rodzinna')}</strong><button class="text-button" id="guide-profile">Zmień lub dodaj sytuację</button></div><div class="case-guide-grid">${[['Rodzicielstwo i opieka','Poznaj różnicę między urlopem macierzyńskim a zasiłkiem macierzyńskim. Adopcja i poszczególne formy pieczy mają odrębne warunki.','https://www.zus.pl/swiadczenia/zasilki/zasilek-macierzynski/komu-przysluguje'],['Ubezpieczenie chorobowe','Sprawdź, jakie znaczenie ma Twój tytuł ubezpieczenia. Sama rola rodzica lub opiekuna nie przesądza o wypłacie.','https://www.zus.pl/swiadczenia/zasilki'],['Dokumenty i terminy','Informacje zależą od rodzaju świadczenia oraz osoby wypłacającej zasiłek. Własne wyliczenia i daty zapiszesz w kalkulatorze.','https://www.zus.pl/swiadczenia/zasilki/zasilek-macierzynski/niezbedne-dokumenty']].map(([title,body,url])=>`<section class="case-card"><h2>${title}</h2><p>${body}</p><a href="${url}" target="_blank" rel="noopener noreferrer">Przeczytaj w ZUS ↗</a></section>`).join('')}</div><section class="case-guide-cta case-card"><div><h2>Sprawdź swoją sytuację w kalkulatorze</h2><p>Podaj własne dane albo wczytaj dokument. Tożsamość z logowania nie jest informacją o ubezpieczeniu i zarobkach.</p></div><button class="primary" id="guide-calculator">Otwórz Zintegrowany Kalkulator</button></section><button class="text-button" id="guide-special">Potrzebuję wsparcia w szczególnej sytuacji</button>${rightsGuideHtml()}`;main.querySelector('#guide-profile').onclick=()=>show('profile');main.querySelector('#guide-calculator').onclick=()=>show('calculator');main.querySelector('#guide-special').onclick=showSpecialSupport;}
function editFamily(id){const record=id?profile.familySituations.find(r=>r.situationId===id):null,initial=record||{situationId:newSituationId()};sheetContent(record?'Popraw informacje o dziecku i sytuacji':'Dodaj dziecko lub sytuację rodzinną',caseOnboardingHtml('',initial,true));bindCaseProfileForm(sheet,data=>{const family=normalizeFamilySituation({...initial,...data,formal:true});persist({...family,familySituations:profile.familySituations});calculator.useProfile();sheet.close();show('profile');notify('Zapisano sytuację rodzinną. Dotychczasowe scenariusze zostały zachowane.');},{profile:initial,edit:true,startStep:record?2:0,onCancel:()=>sheet.close(),onSpecial:showSpecialSupport});}
function renderProfile(main){main.innerHTML=`<div class="case-page-heading"><span class="eyebrow">Wasza rodzina</span><h1>Dzieci i sytuacje rodzinne</h1><p>Każde dziecko ma oddzielne informacje. Możesz dodać ciążę, adopcję lub pieczę bez ponownej rejestracji. Wybrana sytuacja podpowiada dane nowego scenariusza; nie zmienia zapisanych wyników.</p><button class="primary" id="profile-add-situation">Dodaj dziecko lub sytuację</button></div><div class="case-card-grid">${profile.familySituations.map(record=>`<section class="case-card ${record.situationId===profile.situationId?'case-selected':''}"><span class="eyebrow">${record.situationId===profile.situationId?'Aktualnie wybrana sytuacja':'Zapisana sytuacja'}</span><h2>${esc(CASE_STAGES[record.caseStage])}</h2><p>${esc(CASE_ROLES[record.parentRole])}</p>${record.caseStage==='other-care'?`<p>${{guardian:'Opiekun prawny ustanowiony przez sąd',family:'Członek rodziny pomagający w opiece',other:'Inna forma opieki',unknown:'Forma opieki do uzupełnienia'}[record.careStatus]}</p>`:''}${record.children.length?record.children.map((child,index)=>`<article class="case-child-summary"><h3>${esc(child.name||'Dziecko '+(index+1))}</h3><p>${child.birthDate?calendarDate(child.birthDate,{long:true}):'Data urodzenia: nie podano'}</p><button class="text-button" data-select-child="${esc(child.id)}" data-child-situation="${esc(record.situationId)}">${record.situationId===profile.situationId&&record.activeChildId===child.id?'Wybrane do nowego scenariusza':'Wybierz do nowego scenariusza'}</button></article>`).join(''):'<p>Informacje o dziecku można uzupełnić później.</p>'}<dl class="case-facts">${[['Przewidywany poród',record.caseStage==='pregnancy'?record.eventDate:''],['Przyjęcie na wychowanie',record.placementDate],['Prawomocność adopcji',record.adoptionCourtDate]].filter(([,date])=>date).map(([label,date])=>`<div><dt>${label}</dt><dd>${calendarDate(date,{long:true})}</dd></div>`).join('')}</dl><button class="secondary" data-edit-situation="${esc(record.situationId)}">Popraw informacje</button><button class="text-button" data-use-situation="${esc(record.situationId)}">Wybierz tę sytuację</button></section>`).join('')}<section class="case-card"><h2>Dane osoby korzystającej z aplikacji</h2><p>To dane do personalizacji. Nie zastępują danych wymaganych we wniosku ani nie potwierdzają ubezpieczenia.</p><form id="identity-profile-form"><label class="calc-field"><span>Twoje imię i nazwisko (opcjonalnie)</span><input name="applicantName" maxlength="200" value="${esc(profile.applicantName)}"></label><label class="calc-field"><span>Twoja data urodzenia (opcjonalnie)</span><input name="applicantBirthDate" type="date" value="${esc(profile.applicantBirthDate)}"></label><button class="secondary">Zapisz dane osoby</button><p id="identity-profile-error" role="alert" class="calc-error" hidden></p></form><button class="text-button" id="profile-data">Dane i dokumenty</button><button class="text-button" id="profile-special">Wsparcie w szczególnej sytuacji</button></section></div>`;
main.querySelector('#profile-add-situation').onclick=()=>editFamily();main.querySelectorAll('[data-edit-situation]').forEach(b=>b.onclick=()=>editFamily(b.dataset.editSituation));main.querySelectorAll('[data-use-situation]').forEach(b=>b.onclick=()=>{persist(selectFamilySituation(profile,b.dataset.useSituation));calculator.useProfile();show('profile');});main.querySelectorAll('[data-select-child]').forEach(b=>b.onclick=()=>{const selected=selectFamilySituation(profile,b.dataset.childSituation);persist({...selected,activeChildId:b.dataset.selectChild});calculator.useProfile();show('profile');});main.querySelector('#identity-profile-form').onsubmit=e=>{e.preventDefault();try{persist(Object.fromEntries(new FormData(e.target)));notify('Zapisano dane osoby.');}catch(error){const el=main.querySelector('#identity-profile-error');el.hidden=false;el.textContent=error.message;}};main.querySelector('#profile-data').onclick=()=>show('documents');main.querySelector('#profile-special').onclick=showSpecialSupport;
}
planner.setOnChange(()=>{calculator.invalidateRules();if(profile&&active==='calendar')show('calendar');});
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)sheet.close();}});
try{await planner.load();if(profile&&profile.onboardingComplete){persist({formal:true});shell();show('guide');}else onboarding();}catch{app.innerHTML='<main class="welcome"><h1>Nie udało się wczytać aplikacji</h1><p>Odśwież stronę i sprawdź połączenie.</p></main>';}
